```tsx
import { useId } from "react";
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({ title, detail, minutes, done, onToggle }: ChecklistItemProps) {
  const titleId = useId();
  const detailId = useId();

  return (
    <div className={done ? "checklist-item is-done" : "checklist-item"}>
      <button
        type="button"
        className="checklist-item__check"
        aria-pressed={done}
        aria-labelledby={titleId}
        aria-describedby={detailId}
        onClick={onToggle}
      >
        <span className="checklist-item__tick" aria-hidden="true" />
      </button>
      <div className="checklist-item__text">
        <p id={titleId} className="checklist-item__title">{title}</p>
        <p id={detailId} className="checklist-item__detail">{detail}</p>
      </div>
      <span className="checklist-item__minutes">{minutes} min</span>
    </div>
  );
}
```

```css
.checklist-item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: clamp(0.75rem, 1.5vw, 1.25rem);
  padding: clamp(0.75rem, 1.4vw, 1.1rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
  font: inherit;
}

.checklist-item__check {
  display: grid;
  place-items: center;
  flex: none;
  width: clamp(2.5rem, 3.4vw, 2.9rem);
  height: clamp(2.5rem, 3.4vw, 2.9rem);
  padding: 0;
  border: 2px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition: background-color 180ms ease, border-color 180ms ease;
}

.checklist-item__check:hover {
  border-color: var(--ink);
}

.checklist-item__tick {
  display: block;
  width: 0.3em;
  height: 0.6em;
  margin-top: -0.12em;
  border: solid var(--slide);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg) scale(0.4);
  opacity: 0;
  transition: opacity 180ms ease, transform 180ms ease;
}

.checklist-item.is-done .checklist-item__check {
  background: var(--myelin);
  border-color: var(--myelin);
}

.checklist-item.is-done .checklist-item__tick {
  opacity: 1;
  transform: rotate(45deg) scale(1);
}

.checklist-item__text {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}

.checklist-item__title {
  margin: 0;
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  font-weight: 600;
  color: var(--ink);
  transition: color 180ms ease;
}

.checklist-item__detail {
  margin: 0;
  font-size: clamp(0.85rem, 1.2vw, 0.975rem);
  color: var(--muted);
}

.checklist-item.is-done .checklist-item__title {
  font-weight: 400;
  color: var(--muted);
}

.checklist-item__minutes {
  font-size: clamp(0.85rem, 1.2vw, 0.975rem);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

:root[data-motion="reduce"] .checklist-item__check,
:root[data-motion="reduce"] .checklist-item__tick,
:root[data-motion="reduce"] .checklist-item__title {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item__check,
  .checklist-item__tick,
  .checklist-item__title {
    transition: none;
  }
}
